Item.method_code:
/*　
    親アイテムからドキュメントとの紐づきを削除した際、ドキュメントのパーミッションを更新する。
    削除Beforeの処理
        ・親アイテム変更前に紐づいているドキュメントを取得しておく
            config_id,parent_order_no の文字列のListで送る（単に紐づいているドキュメントとした場合、Relationの追加・削除が判定できない）
        
    削除Afterの処理
        ・親アイテム変更後に紐づいているドキュメントを取得して、変更前との差分で削除されたリレーションを特定し、削除時処理を実施
 */

Innovator inn = this.getInnovator();
try{
    //権限付与用
    Aras.Server.Security.Identity adminIdentity = Aras.Server.Security.Identity.GetByName("Administrators");

    string typename = this.getType();
    string itemid = this.getID();
    RequestState.Remove(typename);

    //ドキュメントへのリレーション名取得
    Item docRelationNames = inn.newItem("method","h4_GetDocumentRelationName");
    docRelationNames.setProperty("typename", typename);
    using (CCO.Permissions.GrantIdentity(adminIdentity))
    {
        docRelationNames = docRelationNames.apply();
        if(docRelationNames.isError())
        {
            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));   
        }
    }

    List<string> confList = new List<string>();
	for (int docRelationNameCount = 0; docRelationNameCount < docRelationNames.getItemCount(); docRelationNameCount++)
	{
		string relitemtypeName = docRelationNames.getItemByIndex(docRelationNameCount).getProperty("name", "");
		
        Item docConfIDs = inn.newItem("method","h4_GetDocRelParentConfigID");
        docConfIDs.setProperty("relitemtypeName", relitemtypeName);
        docConfIDs.setProperty("sourceID", itemid);
        using (CCO.Permissions.GrantIdentity(adminIdentity))
        {
            docConfIDs = docConfIDs.apply();
            if(docConfIDs.isError())
            {
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));   
            }
        }
    	
    	for(int docConfCount= 0; docConfIDs.getRelationships().getItemCount() > docConfCount; docConfCount++)
    	{
         	Item rel = docConfIDs.getRelationships().getItemByIndex(docConfCount);
            confList.Add(rel.getProperty("config_id") + "," + rel.getProperty("parent_order_no"));
    	}
	}
	
    if(confList.Count > 0)
    {
        RequestState.Add(typename, confList);
    }

    return this;
}
catch (Exception ex)
{    
    return inn.newError(ex.ToString());
}
}

private void Dummy()
{
